import { Produto } from "../entities/Produto.js";
import { carrinho } from "../utils/carrinho.js";

export class ProdutoRepository {
    
    listar(): Produto[] {
        return carrinho;
    }
    async atualizar(id: number, qty: number){
        const produto = carrinho.find(item => item.id === id);
        if(!produto) {
            return null;
        }
        produto.qty = qty;
        return produto;
    }   
}
